    if(has("bassoon"))return I::bassoon;
    if(has("clarinet"))return I::clarinet;
    if(has("oboe"))return I::oboe;
    if(has("sax"))return I::saxophone;
    if(has("flute"))return I::flute;
    if(has("trombone"))return I::trombone;
    if(has("trumpet"))return I::trumpet;
    if(has("tuba")||has("baritone horn"))return I::tuba;
    if(has("horn"))return I::horn;
    if(has("choir")||has("voice")||has("vocal"))return I::voice;
    if(has("ensemble")||has("orchestra hit")||has("section"))return I::ensemble;
    if(has("cello"))return I::cello;
    if(has("violin")||has("fiddle")||has("strings"))return I::violin;
    if(has("guitar")||has("sitar")||has("bass"))return I::guitar;
    if(has("drum")||has("woodblock"))return I::drum;
    if(has("piano")||has("keyboard")||has("clavinet"))return I::piano;
    if(has("audio")||has("wave"))return I::audio;
    const auto f=family.toLowerCase();
    if(f.contains("woodwind")||f.contains("flute")||f.contains("reeds"))return I::flute;
    if(f.contains("brass"))return I::horn;
    if(f.contains("strings"))return I::violin;
    if(f.contains("chromatic percussion"))return I::mallets;
    if(f.contains("percussion"))return I::drum;
    if(f.contains("synth")||f.contains("sampler"))return I::synth;
    if(f.contains("guitar")||f.contains("bass"))return I::guitar;
    if(f.contains("keyboard")||f.contains("piano")||f.contains("organ"))return I::piano;
    if(f.contains("voice")||f.contains("choir"))return I::voice;
    return I::other;
