inline void drawInstrumentIcon(juce::Graphics& g, juce::Rectangle<float> bounds, InstrumentIcon icon, juce::Colour colour)
{
    if(bounds.isEmpty()) return;
    const float scale=juce::jmin(bounds.getWidth(),bounds.getHeight())/64.0f;
    const auto target=bounds.withSizeKeepingCentre(scale*64.0f,scale*64.0f);
    juce::Graphics::ScopedSaveState save(g);
    g.addTransform(juce::AffineTransform::scale(scale).translated(target.getX(),target.getY()));
    g.setColour(colour);
    g.strokePath(instrumentIconPath(icon),juce::PathStrokeType(2.0f,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));
}
